// Turns one Calendly webhook body into the fields we store.
// Accepts the body directly ({ event, payload }) or wrapped in { body }.
const input = $('When Called By Another Workflow').first().json;
const cfg = $('Load Config').first().json;
const body = input.body ?? input;
const event = body.event;
const p = body.payload ?? {};
const se = p.scheduled_event ?? {};
const host = (se.event_memberships ?? [])[0] ?? {};
const tracking = p.tracking ?? {};

const eventTypeUri = se.event_type ?? '';
const eventTypeUuid = eventTypeUri.split('/').pop();

let sourceKind = 'research';
if (tracking.utm_source === cfg.uxrUtmSource) sourceKind = 'uxr_recruiting';
else if (eventTypeUuid === cfg.roundRobinEventTypeUuid) sourceKind = 'continuous_discovery';

// Same utm parameters as the original booking, so the rebook link matches the outreach link.
const utm = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term']
  .filter((k) => tracking[k])
  .map((k) => `${k}=${encodeURIComponent(tracking[k])}`)
  .join('&');

const name = p.name || [p.first_name, p.last_name].filter(Boolean).join(' ');
const email = (p.email || '').toLowerCase();

// Mock guard: in mock mode only fake participants may enter the table.
let dropReason = null;
if (!['invitee.created', 'invitee.canceled'].includes(event)) dropReason = `ignored event ${event}`;
else if (!p.uri) dropReason = 'payload has no invitee uri';
else if (cfg.mockMode && !new RegExp(cfg.allowedParticipantEmailPattern).test(email)) dropReason = 'mock guard: participant email not allowed';

return [{
  json: {
    valid: dropReason === null,
    drop_reason: dropReason,
    event,
    rescheduled: p.rescheduled === true,
    invitee_uri: p.uri ?? null,
    event_uri: se.uri ?? p.event ?? null,
    event_type_uri: eventTypeUri || null,
    event_name: se.name ?? null,
    source_kind: sourceKind,
    batch_id: sourceKind === 'uxr_recruiting' ? (tracking.utm_campaign ?? null) : null,
    participant_name: name || null,
    participant_first_name: p.first_name || (name ? name.split(' ')[0] : null),
    participant_email: email || null,
    host_name: host.user_name ?? null,
    host_email: (host.user_email || '').toLowerCase() || null,
    starts_at: se.start_time ?? null,
    ends_at: se.end_time ?? null,
    old_invitee: p.old_invitee || null,
    new_invitee: p.new_invitee || null,
    mark_old_invitee: event === 'invitee.created' && p.old_invitee ? p.old_invitee : null,
    cancel_reason: p.cancellation?.reason ?? null,
    canceled_at: p.cancellation?.created_at ?? null,
    reschedule_url: p.reschedule_url ?? null,
    utm,
    is_mock: cfg.mockMode === true,
  },
}];

// Decides the final column values for this invitee row.
// Only the columns in the output are written. Follow-up columns are never reset here.
const ev = $('Normalize Event').first().json;
const existing = $('Find Existing Row').first().json ?? {};
const eventType = $('Get Event Type').first().json ?? {};
const hasRow = existing.id !== undefined && existing.id !== null;

const schedulingUrl = eventType.resource?.scheduling_url;
let bookingLink = ev.reschedule_url;
if (schedulingUrl) {
  bookingLink = ev.utm ? `${schedulingUrl}${schedulingUrl.includes('?') ? '&' : '?'}${ev.utm}` : schedulingUrl;
}

const row = {
  invitee_uri: ev.invitee_uri,
  event_uri: ev.event_uri,
  event_type_uri: ev.event_type_uri,
  event_name: ev.event_name,
  source_kind: ev.source_kind,
  batch_id: ev.batch_id,
  participant_name: ev.participant_name,
  participant_first_name: ev.participant_first_name,
  participant_email: ev.participant_email,
  host_name: ev.host_name,
  host_email: ev.host_email,
  starts_at: ev.starts_at,
  ends_at: ev.ends_at,
  is_mock: ev.is_mock,
};

if (ev.event === 'invitee.created') {
  row.booking_link = bookingLink;
  if (ev.old_invitee) row.rescheduled_from = ev.old_invitee;
  // A cancel can arrive before its create. Then the row keeps its final state.
  const isFinal = ['canceled', 'rescheduled'].includes(existing.booking_status);
  row.booking_status = isFinal ? existing.booking_status : 'active';
  if (!hasRow || !existing.followup_status) row.followup_status = 'pending';
} else {
  if (ev.rescheduled) {
    row.booking_status = 'rescheduled';
    if (ev.new_invitee) row.rescheduled_to = ev.new_invitee;
  } else {
    row.booking_status = 'canceled';
    row.canceled_at = ev.canceled_at || $now.toISO();
    row.cancel_reason = ev.cancel_reason;
  }
  if (!hasRow) row.booking_link = bookingLink;
}

return [{ json: row }];
